WITH with_gaps AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL 30 MINUTES THEN 1 ELSE 0 END AS is_new_burst FROM device_readings), sessionized AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM with_gaps) SELECT device_code, MAX(reading_ts) AS last_reading_ts, MAX(is_new_burst) AS max_is_new_burst, PERCENTILE_APPROX(temp_c, 0.5) AS temp_c_p50 FROM sessionized GROUP BY device_code ORDER BY max_is_new_burst DESC NULLS FIRST
